  Thriller
  Action
  Horror
  Comedy
}

class Screenwriter {
  + Name : string
  + MostSuccessfulFilm : string
}

class Screenplay {
  + Title : string
  + Version : string
  + Date : date
  + NumberOfScenes : int
  + Plot : string
}

class Novel {
  + Title : string
  + Author : string
}

class Concept {
}

class Role {
}

FilmSet "1..*" -- "1..*" Film
Film "1" -- "1" Genre
Film "1" -- "1" Screenplay
Screenplay "1" -- "1" Film
Screenplay "1" -- "1" Screenwriter
Screenplay "0..1" -- "0..1" Novel
